353	        switch (type.getTypeID()) {
354	            case Types.BIGINT:
355	                return Long.class;
356	            case Types.DECIMAL:
357	            case Types.DOUBLE:
358	            case Types.REAL:
359	                if (CommonUtils.toInt(type.getScale()) > 0) {
360	                    // Workaround for Oracle #3062
361	                    return Double.class;
362	                }
363	                return BigDecimal.class;
