366	                    // Workaround for Oracle #3062
367	                    return Float.class;
368	                }
369	                return BigDecimal.class;
370	            //Workaround for MySQL Unsigned INTEGER #8786
371	            case Types.INTEGER:
372	                return Long.class;
373	            case Types.SMALLINT:
374	            //Workaround for MySQL Unsigned SMALLINT #10239
375	                return Integer.class;
376	            case Types.TINYINT:
377	                return Short.class;
