379	                if (CommonUtils.toInt(type.getPrecision()) <= 1) {
380	                    return Byte.class;
381	                } else {
382	                    // bit string (hopefully long is enough)
383	                    return Long.class;
384	                }
385	            case Types.NUMERIC:
386	                return BigDecimal.class;
387	            default:
388	                if (CommonUtils.toInt(type.getScale()) > 0) {
389	                    return Double.class;
390	                } else {
391	                    return Long.class;
392	                }
393	        }
